import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Testing Ceph for the Cloud, in the Cloud - Adam Wolfe Gordon, DigitalOcean","description":"","frontmatter":{"title":"Testing Ceph for the Cloud, in the Cloud - Adam Wolfe Gordon, DigitalOcean","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph测试","云存储","自动化测试","DigitalOcean","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Testing_Ceph_for_the_Cloud_in_the_Cloud_-_Adam_Wolfe_Gordon_DigitalOcean.md","filePath":"posts/2019/Testing_Ceph_for_the_Cloud_in_the_Cloud_-_Adam_Wolfe_Gordon_DigitalOcean.md","lastUpdated":1780459816000}'),l={name:"posts/2019/Testing_Ceph_for_the_Cloud_in_the_Cloud_-_Adam_Wolfe_Gordon_DigitalOcean.md"};function n(_,e,r,s,p,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>Adam Wolfe Gordon，来自DigitalOcean存储团队，在KubeCon会议上分享了他们如何使用云资源搭建Ceph测试环境的过程和挑战。</p><p><strong>会议背景</strong></p><p>DigitalOcean是一家公有云提供商，基于Ceph技术构建了其存储产品。随着业务规模扩大，DigitalOcean开始需要更多控制权，以满足服务质量要求，并解决对象存储中的扩展限制和bug。</p><p><strong>主要议题</strong></p><ol><li><p><strong>Ceph测试环境搭建</strong>：</p><ul><li>DigitalOcean决定搭建自己的Ceph测试环境，并开发内部工具以实现自动化测试。</li><li>由于Toothology框架的限制，DigitalOcean需要进行一些调整，例如解决DNS名称通信和网络配置问题。</li></ul></li><li><p><strong>搭建测试环境遇到的挑战</strong>：</p><ul><li><strong>Toothology框架的限制</strong>：DigitalOcean通过安装DNS Masq和配置hosts文件来解决DNS通信问题，通过黑名单规则解决网络配置问题，通过创建符号链接解决Ceph包路径问题，修改代码以跳过SHA-1验证。</li><li><strong>自动化测试环境搭建</strong>：DigitalOcean使用Terraform和Ansible自动化脚本搭建Ceph测试环境，包括Droplets、Paddles服务器、Head节点和Test节点，用户可以通过运行单个命令来启动测试环境。</li></ul></li></ol><p><strong>行动计划</strong></p><ul><li>DigitalOcean将继续优化Ceph测试环境，并开源其自动化脚本，以帮助社区成员快速搭建测试环境。</li><li>DigitalOcean将继续向Ceph社区贡献代码，并积极参与社区活动。</li></ul><p><strong>会议总结</strong></p><p>本次会议介绍了DigitalOcean如何搭建Ceph测试环境，并分享了在搭建过程中遇到的挑战和解决方案。DigitalOcean的自动化脚本为Ceph社区提供了宝贵的资源，有助于促进Ceph技术的发展和应用。</p>',10)])])}const c=t(l,[["render",n]]);export{h as __pageData,c as default};
